<?php
require_once __DIR__.'/../configuracion/admin-ui.php';
$courses=neo_courses();$course=(int)app_value($_GET,'curso_seleccionado',neo_current_course($courses));$courseName='';foreach($courses as $c)if((int)$c['id_curso']===$course)$courseName=$c['nombre'];
$labels=array('Bebés de 3 a 24 meses','De 2 a 3 años · Verde','De 3 a 5 años · Azul','De 5 a 10 años · Rojo','Aquagym','Matronatación');
// One grouped query; categories are mutually exclusive and closed applicants are not waiting.
$counts=app_rows('SELECT edad_espera,COUNT(*) AS total,SUM(incorporado=1) AS incorporados,SUM(incorporado=0 AND motivo_baja NOT IN (0,1)) AS descartados,SUM(incorporado=0 AND motivo_baja=0) AS espera,SUM(incorporado=0 AND motivo_baja=1) AS baja_incorporado FROM (SELECT l.*,EXISTS(SELECT 1 FROM alumnos a WHERE a.id_usuario=l.id_usuario AND a.id_curso=l.id_curso AND a.id_centro=l.id_centro) AS incorporado FROM lista_espera l WHERE l.id_centro=? AND l.id_curso=?) x GROUP BY edad_espera','ii',array((int)$centro_actual,$course));
$map=array();$totals=array('espera'=>0,'incorporados'=>0,'descartados'=>0);foreach($counts as $r){$r['incorporados']+=(int)$r['baja_incorporado'];$map[(int)$r['edad_espera']]=$r;foreach($totals as $k=>$v)$totals[$k]+=(int)$r[$k];if(!isset($labels[(int)$r['edad_espera']]))$labels[(int)$r['edad_espera']]='Otros grupos';}
neo_page_start('Listas de espera','Consulta la demanda por grupo y distingue las solicitudes pendientes de las incorporaciones y bajas.','Alumnos');
?>
<section class="neo-panel"><form method="get" class="neo-filters"><label class="grow">Curso<select name="curso_seleccionado"><?php foreach($courses as $c){ ?><option value="<?=(int)$c['id_curso']?>" <?=((int)$c['id_curso']===$course?'selected':'')?>><?=app_escape($c['nombre'])?></option><?php } ?></select></label><button>Ver curso</button><a class="neo-button secondary" href="exportar_lista_espera.php?id_curso_lista=<?=$course?>" target="_blank" rel="noopener">Exportar listado</a><a class="neo-button" href="/alumnos/nuevo_alumno.php">+ Añadir alumno</a></form></section>
<div class="neo-stats"><?php foreach(array('espera'=>'Pendientes de plaza','incorporados'=>'Incorporados al centro','descartados'=>'Descartados') as $key=>$label){ ?><div class="neo-stat"><strong><?=$totals[$key]?></strong><span><?=$label?></span></div><?php } ?></div>
<div class="neo-table-wrap"><table class="neo-data-table"><caption><?=app_escape($courseName)?></caption><thead><tr><th>Grupo</th><th>Pendientes</th><th>Incorporados</th><th>Descartados</th><th>Consulta</th></tr></thead><tbody>
<?php foreach($labels as $id=>$label){$r=$map[$id]??array('espera'=>0,'incorporados'=>0,'descartados'=>0); ?><tr><td><strong><?=app_escape($label)?></strong></td><td class="number"><span class="neo-pill <?=(int)$r['espera']?'warning':'muted'?>"><?=(int)$r['espera']?></span></td><td class="number"><?=(int)$r['incorporados']?></td><td class="number"><?=(int)$r['descartados']?></td><td><a class="neo-button secondary" href="lista_espera.php?edad_lista=<?=(int)$id?>&amp;id_curso_lista=<?=$course?>">Ver lista →</a></td></tr><?php } ?></tbody></table></div><p class="neo-help">Las solicitudes descartadas ya no se cuentan como pendientes. Cada solicitud figura en un único estado.</p>
<?php neo_page_end();
